/**
 * One immutable Hugging Face file: the commit it is pinned to plus the exact
 * size and SHA-256 its bytes must match before they are used or cached.
 * The modules beside this file are generated by scripts/pin-model-manifests.mjs.
 */
export interface PinnedModelFile {
  readonly repo: string;
  readonly revision: string;
  readonly path: string;
  readonly byteLength: number;
  readonly sha256: string;
  /** SPDX-style license id from the repository card at that revision. */
  readonly license: string;
}

export function pinnedModelFileUrl(file: PinnedModelFile): string {
  return `https://huggingface.co/${file.repo}/resolve/${file.revision}/${file.path}`;
}
